// O no do agente devolve apenas 'output', por isso recuperamos o cliente
// correspondente pelo indice do item, que o agente preserva.
const base = $('Mensagem por template').all();

return $input.all().map((item, i) => {
  const original = base[i].json;
  const { mensagem_template, usar_ia, ...resto } = original;
  const texto = String(item.json.output ?? '').trim();
  const falhou = texto === '';

  return {
    json: {
      ...resto,
      mensagem: falhou ? mensagem_template : texto,
      origem: falhou ? 'template (fallback: a IA não respondeu)' : 'ia',
    },
  };
});

return $input.all().map((item) => {
  const { mensagem_template, usar_ia, ...resto } = item.json;
  return { json: { ...resto, mensagem: mensagem_template, origem: 'template' } };
});

// Um alerta com a lista toda, em vez de um ping por cliente. Dez notificacoes
// seguidas no telefone sao ruido; uma com dez linhas e informacao.
const falhas = $input.all().map((i) => i.json);
const linhas = falhas
  .map((f) => `- ${f.nome} <${f.email}>\n  ${f.erro_validacao}`)
  .join('\n');

const texto = [
  `Assistente de investimentos: ${falhas.length} email(s) nao enviado(s)`,
  ``,
  `Modo: ${falhas[0]?.modo ?? 'desconhecido'}`,
  `Momento: ${new Date().toISOString()}`,
  ``,
  linhas,
].join('\n');

return [{ json: { texto, total: falhas.length } }];
